import{_ as n,C as o,o as e,c as s,a2 as t,b as i,w as r,a as l,E as c,a3 as f}from"./chunks/framework.CZqXuAiL.js";const k=JSON.parse(`{"title":"Glacier Theme for Pterodactyl","description":"A calm, Apple-grade sidebar theme for Pterodactyl Panel — dark and light modes, glass, 16 background patterns, console zones, dashboard cards and a full tab manager, configured entirely from the admin UI.","frontmatter":{"title":"Glacier Theme for Pterodactyl","description":"A calm, Apple-grade sidebar theme for Pterodactyl Panel — dark and light modes, glass, 16 background patterns, console zones, dashboard cards and a full tab manager, configured entirely from the admin UI.","head":[["meta",{"name":"og:title","content":"Glacier — Apple-Grade Sidebar Theme for Pterodactyl"}],["meta",{"name":"og:description","content":"A Blueprint theme that replaces Pterodactyl's top navigation with a customizable sidebar and reskins the whole panel — zero core-file replacement, zero external assets."}]]},"headers":[],"relativePath":"glacier/index.md","filePath":"glacier/index.md","lastUpdated":1785230800000}`),v={name:"glacier/index.md"};function h(p,a,g,u,m,b){const d=o("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="glacier-theme-for-pterodactyl" tabindex="-1" data-v-ac823faf>Glacier Theme for Pterodactyl <a class="header-anchor" href="#glacier-theme-for-pterodactyl" aria-label="Permalink to &quot;Glacier Theme for Pterodactyl&quot;" data-v-ac823faf>​</a></h1><p data-v-ac823faf><strong data-v-ac823faf>A calm, Apple-grade sidebar theme for Pterodactyl Panel</strong>, built on the Blueprint framework. Glacier replaces the stock top navigation with a clean sidebar, reskins every page in dark and light mode, and gives you deep, code-free control over backgrounds, glass, colors and tabs — with <strong data-v-ac823faf>zero core-file replacement</strong> and <strong data-v-ac823faf>zero external assets</strong>.</p><div class="tip custom-block" style="margin-top:1.5rem;" data-v-ac823faf><p data-v-ac823faf><strong data-v-ac823faf>❄️ Built for ALTIS TECH SOLUTIONS</strong><a href="https://xdp.network" target="_blank" rel="noreferrer" data-v-ac823faf>xdp.network</a> · Single <code data-v-ac823faf>.blueprint</code> package, installed on the panel</p></div><hr data-v-ac823faf><h2 id="architecture" tabindex="-1" data-v-ac823faf>Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;" data-v-ac823faf>​</a></h2>',5)),(e(),i(f,null,{default:r(()=>[c(d,{id:"mermaid-15",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20subgraph%20Panel%5B%22Pterodactyl%20Panel%22%5D%0A%20%20%20%20%20%20%20%20BP%5B%22Blueprint%20framework%22%5D%0A%20%20%20%20%20%20%20%20EXT%5B%22Glacier%20extension%3Cbr%2F%3Econtroller.php%20%C2%B7%20view.blade.php%22%5D%0A%20%20%20%20%20%20%20%20DB%5B(%22Panel%20settings%20table%3Cbr%2F%3Eglacier%3A%3A*%20keys%22)%5D%0A%20%20%20%20%20%20%20%20WRAP%5B%22Wrapper%20blades%3Cbr%2F%3Edashboard%20%2B%20admin%22%5D%0A%20%20%20%20%20%20%20%20VARS%5B%22variables.blade.php%3Cbr%2F%3Eserver-rendered%20CSS%20tokens%22%5D%0A%20%20%20%20%20%20%20%20EXT%20--%3E%20DB%0A%20%20%20%20%20%20%20%20EXT%20--%3E%20WRAP%0A%20%20%20%20%20%20%20%20WRAP%20--%3E%20VARS%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20Browser%5B%22Every%20page%20load%22%5D%0A%20%20%20%20%20%20%20%20BOOT%5B%22Anti-FOUC%20boot%3Cbr%2F%3Einline%20data%20attributes%22%5D%0A%20%20%20%20%20%20%20%20CSS%5B%229%20CSS%20libraries%3Cbr%2F%3Ecore%20%C2%B7%20sidebar%20%C2%B7%20console%20%C2%B7%20panel%20%C2%B7%20home%20%E2%80%A6%22%5D%0A%20%20%20%20%20%20%20%20JS%5B%228%20JS%20libraries%3Cbr%2F%3Esidebar%20%C2%B7%20console-stats%20%C2%B7%20home%20%C2%B7%20activity%20%E2%80%A6%22%5D%0A%20%20%20%20%20%20%20%20VARS%20--%3E%20BOOT%0A%20%20%20%20%20%20%20%20BOOT%20--%3E%20CSS%0A%20%20%20%20%20%20%20%20BOOT%20--%3E%20JS%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20Stock%5B%22Stock%20React%20app%20(untouched)%22%5D%0A%20%20%20%20%20%20%20%20REACT%5B%22React%20DOM%3Cbr%2F%3Enever%20moved%2C%20never%20forked%22%5D%0A%20%20%20%20%20%20%20%20JS%20-.-%3E%7C%22data-*%20attributes%20%2B%3Cbr%2F%3EMutationObserver%20re-assert%22%7C%20REACT%0A%20%20%20%20end%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t(`<p data-v-ac823faf>Glacier never edits a Pterodactyl core file. Blueprint renders Glacier&#39;s wrapper blades at the end of every page; those emit a server-rendered design-token block (so the very first paint is already themed) and load Glacier&#39;s CSS/JS libraries. The JavaScript enhances the stock React UI through <code data-v-ac823faf>data-*</code> attributes and a MutationObserver — attributes survive React re-renders, so the theme is resilient to panel updates.</p><hr data-v-ac823faf><h2 id="key-features" tabindex="-1" data-v-ac823faf>Key Features <a class="header-anchor" href="#key-features" aria-label="Permalink to &quot;Key Features&quot;" data-v-ac823faf>​</a></h2><ul data-v-ac823faf><li data-v-ac823faf><strong data-v-ac823faf>🌗 Full dark and light design system.</strong> Separate 10-color palettes per mode (accent, background, surface, elevated, ink, muted, border, success, warning, danger), a one-click seed-color palette generator, curated presets, and dark / light / auto (follows the OS) modes. Users can flip modes themselves from the account menu if you allow it.</li><li data-v-ac823faf><strong data-v-ac823faf>🧭 Sidebar navigation, three docks.</strong> Replaces the top nav with an expanded or collapsed sidebar rail that sticks to the edge or floats in two styles. Five tab row effects (box, rounded, pill, dot, solid), hover styles, category headers, icon scale, custom logo and panel name.</li><li data-v-ac823faf><strong data-v-ac823faf>🗂️ A real tab manager.</strong> Reorder, relabel, re-icon or hide any sidebar tab; add redirect tabs linking anywhere; keep a separate tab list for server pages; addon tabs are imported automatically into a &quot;More&quot; group.</li><li data-v-ac823faf><strong data-v-ac823faf>🖥️ Console command center.</strong> Stats blocks (CPU, memory, network, uptime) as sparkline cards, classic icons or hidden — placeable above, beside or below the terminal with a drag-and-drop zones editor. Bandwidth graph (minimal or advanced), floating command input, custom console color, and a per-server server bar in the sidebar.</li><li data-v-ac823faf><strong data-v-ac823faf>🎴 Dashboard server cards.</strong> Banner or fade cover-image cards with per-server image rules, rows (elongated) or grid (shrink) layout, live CPU/memory/disk stats, state dots, and an optional welcome bar for non-admin users.</li><li data-v-ac823faf><strong data-v-ac823faf>🖼️ Backgrounds without assets.</strong> None, sixteen pure-CSS patterns (grid, waves, hex, circuit, topo, weave, brick…) with size and opacity controls, or your own image by URL or direct upload with opacity, blur and dim. Separate login-page background and login card alignment.</li><li data-v-ac823faf><strong data-v-ac823faf>🔍 Ctrl+K search.</strong> A command-palette search across servers and pages with keyboard navigation, built into an optional topbar with clock (12/24 h, timezone label, date formats).</li><li data-v-ac823faf><strong data-v-ac823faf>📁 File manager refinement.</strong> File browser container opacity/blur, custom or legacy icons with per-type colors, row tinting, sort animations, and an optional VS Code-style file tree on the editor with a drag-resize sash.</li><li data-v-ac823faf><strong data-v-ac823faf>📣 Announcements and extras.</strong> Multi-entry markdown announcements, a dismissable banner with type and CTA, custom footer text, login watermark, custom favicon and browser theme-color.</li><li data-v-ac823faf><strong data-v-ac823faf>🔒 Privacy mode + per-user settings.</strong> Users can blur IPs and server addresses panel-wide, toggle interface sounds, switch dark/light, and enable the editor file tree — all per-user, stored locally, admin-defaultable.</li><li data-v-ac823faf><strong data-v-ac823faf>📦 Import/export + factory reset.</strong> The entire configuration round-trips as JSON from the admin hub, and every change previews live before you save.</li></ul><hr data-v-ac823faf><h2 id="quick-install" tabindex="-1" data-v-ac823faf>Quick Install <a class="header-anchor" href="#quick-install" aria-label="Permalink to &quot;Quick Install&quot;" data-v-ac823faf>​</a></h2><div class="language-bash vp-adaptive-theme" data-v-ac823faf><button title="Copy Code" class="copy" data-v-ac823faf></button><span class="lang" data-v-ac823faf>bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0" data-v-ac823faf><code data-v-ac823faf><span class="line" data-v-ac823faf><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;" data-v-ac823faf># place glacier-v1.0.0.blueprint in /var/www/pterodactyl, then:</span></span>
<span class="line" data-v-ac823faf><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;" data-v-ac823faf>blueprint</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;" data-v-ac823faf> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;" data-v-ac823faf> glacier-v1.0.0</span></span></code></pre></div><p data-v-ac823faf>Open <strong data-v-ac823faf>Admin → Extensions → Glacier</strong> — sensible defaults apply on first load, so the panel looks right before you change a thing. See <a href="./getting-started/installation" data-v-ac823faf>Installation</a> for verification and troubleshooting.</p><hr data-v-ac823faf><h2 id="why-glacier-instead-of" tabindex="-1" data-v-ac823faf>Why Glacier instead of… <a class="header-anchor" href="#why-glacier-instead-of" aria-label="Permalink to &quot;Why Glacier instead of…&quot;" data-v-ac823faf>​</a></h2><table tabindex="0" data-v-ac823faf><thead data-v-ac823faf><tr data-v-ac823faf><th data-v-ac823faf></th><th style="text-align:center;" data-v-ac823faf>Glacier</th><th style="text-align:center;" data-v-ac823faf>Stock panel</th><th style="text-align:center;" data-v-ac823faf>CSS-only themes</th></tr></thead><tbody data-v-ac823faf><tr data-v-ac823faf><td data-v-ac823faf>Sidebar navigation</td><td style="text-align:center;" data-v-ac823faf>✅ three docks, five tab effects</td><td style="text-align:center;" data-v-ac823faf>❌ top nav only</td><td style="text-align:center;" data-v-ac823faf>⚠️ cosmetic, breaks often</td></tr><tr data-v-ac823faf><td data-v-ac823faf>Dark <strong data-v-ac823faf>and</strong> light palettes</td><td style="text-align:center;" data-v-ac823faf>✅ 10 tokens per mode + presets</td><td style="text-align:center;" data-v-ac823faf>❌ dark only</td><td style="text-align:center;" data-v-ac823faf>⚠️ usually dark only</td></tr><tr data-v-ac823faf><td data-v-ac823faf>Console layout editor</td><td style="text-align:center;" data-v-ac823faf>✅ drag-and-drop zones</td><td style="text-align:center;" data-v-ac823faf>❌ fixed layout</td><td style="text-align:center;" data-v-ac823faf>❌</td></tr><tr data-v-ac823faf><td data-v-ac823faf>Tab manager (reorder / hide / redirect)</td><td style="text-align:center;" data-v-ac823faf>✅</td><td style="text-align:center;" data-v-ac823faf>❌</td><td style="text-align:center;" data-v-ac823faf>❌</td></tr><tr data-v-ac823faf><td data-v-ac823faf>Per-user settings (privacy, sounds, tree)</td><td style="text-align:center;" data-v-ac823faf>✅</td><td style="text-align:center;" data-v-ac823faf>❌</td><td style="text-align:center;" data-v-ac823faf>❌</td></tr><tr data-v-ac823faf><td data-v-ac823faf>Core files replaced</td><td style="text-align:center;" data-v-ac823faf>✅ none</td><td style="text-align:center;" data-v-ac823faf>—</td><td style="text-align:center;" data-v-ac823faf>⚠️ sometimes</td></tr><tr data-v-ac823faf><td data-v-ac823faf>External assets loaded</td><td style="text-align:center;" data-v-ac823faf>✅ none</td><td style="text-align:center;" data-v-ac823faf>—</td><td style="text-align:center;" data-v-ac823faf>⚠️ fonts/CDN common</td></tr></tbody></table><blockquote data-v-ac823faf><p data-v-ac823faf><strong data-v-ac823faf>Bottom line:</strong> CSS-only themes repaint the stock layout; Glacier restructures navigation, console and dashboard while leaving every core file — and every other extension — untouched.</p></blockquote><hr data-v-ac823faf><div class="tip custom-block" data-v-ac823faf><p class="custom-block-title" data-v-ac823faf>VERIFIED LIVE</p><p data-v-ac823faf>Every surface was verified on a real Pterodactyl 1.12 panel during development: sidebar docks and tab effects, console zones in all nine placements, dashboard cards in both layouts, the file editor tree, the activity feed, light mode, and the mobile drawer — via automated browser screenshots at desktop and phone widths.</p></div><hr data-v-ac823faf><h2 id="next-steps" tabindex="-1" data-v-ac823faf>Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;" data-v-ac823faf>​</a></h2><ul data-v-ac823faf><li data-v-ac823faf><strong data-v-ac823faf><a href="./getting-started/installation" data-v-ac823faf>Installation →</a></strong> — requirements, install, verify, uninstall.</li><li data-v-ac823faf><strong data-v-ac823faf><a href="./configuration/reference" data-v-ac823faf>Configuration Reference →</a></strong> — every setting, every default.</li><li data-v-ac823faf><strong data-v-ac823faf><a href="./user-guide/admin-hub" data-v-ac823faf>Admin Hub →</a></strong> — a tour of the settings UI.</li></ul><hr data-v-ac823faf><div class="footer-note" data-v-ac823faf><p data-v-ac823faf><strong data-v-ac823faf>Developed for <a href="https://xdp.network" target="_blank" rel="noreferrer" data-v-ac823faf>ALTIS TECH SOLUTIONS</a></strong></p><p data-v-ac823faf>Questions or licensing — reach us at <a href="https://xdp.network" target="_blank" rel="noreferrer" data-v-ac823faf>xdp.network</a>.</p></div>`,19))])}const x=n(v,[["render",h],["__scopeId","data-v-ac823faf"]]);export{k as __pageData,x as default};
